"""
ReflectionScorer — pre-tournament self-critique filter.
Scores hypotheses on mechanism clarity, falsifiability, and novelty.
Kills weak hypotheses BEFORE they waste tournament debate compute.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Optional


KILL_THRESHOLD = 3.0
REFINE_THRESHOLD = 5.0

WEIGHT_MECHANISM = 0.4
WEIGHT_FALSIFICATION = 0.3
WEIGHT_NOVELTY = 0.3


@dataclass
class ReflectionScore:
    hypothesis_id: str
    mechanism_score: int
    falsification_score: int
    novelty_evidence_score: int
    verdict: str = ""
    refinement_suggestion: str = ""
    critique_text: str = ""

    def __post_init__(self):
        if not self.verdict:
            self.verdict = score_verdict(self.aggregate)

    @property
    def aggregate(self) -> float:
        return (
            self.mechanism_score * WEIGHT_MECHANISM
            + self.falsification_score * WEIGHT_FALSIFICATION
            + self.novelty_evidence_score * WEIGHT_NOVELTY
        )

    def to_dict(self) -> dict:
        return {
            "hypothesis_id": self.hypothesis_id,
            "mechanism_score": self.mechanism_score,
            "falsification_score": self.falsification_score,
            "novelty_evidence_score": self.novelty_evidence_score,
            "aggregate": round(self.aggregate, 2),
            "verdict": self.verdict,
            "refinement_suggestion": self.refinement_suggestion,
            "critique_text": self.critique_text,
        }

    @classmethod
    def from_dict(cls, d: dict) -> ReflectionScore:
        return cls(
            hypothesis_id=d["hypothesis_id"],
            mechanism_score=d["mechanism_score"],
            falsification_score=d["falsification_score"],
            novelty_evidence_score=d["novelty_evidence_score"],
            verdict=d.get("verdict", ""),
            refinement_suggestion=d.get("refinement_suggestion", ""),
            critique_text=d.get("critique_text", ""),
        )


def score_verdict(aggregate: float) -> str:
    if aggregate < KILL_THRESHOLD:
        return "KILL"
    if aggregate < REFINE_THRESHOLD:
        return "REFINE"
    return "PASS"


@dataclass
class ReflectionResult:
    scores: list[ReflectionScore]
    passed: list[str] = field(default_factory=list)
    refined: list[str] = field(default_factory=list)
    killed: list[str] = field(default_factory=list)

    def __post_init__(self):
        if not self.passed and not self.refined and not self.killed:
            self._classify()

    def _classify(self):
        self.passed = [s.hypothesis_id for s in self.scores if s.verdict == "PASS"]
        self.refined = [s.hypothesis_id for s in self.scores if s.verdict == "REFINE"]
        self.killed = [s.hypothesis_id for s in self.scores if s.verdict == "KILL"]

    def to_dict(self) -> dict:
        return {
            "scores": [s.to_dict() for s in self.scores],
            "passed": list(self.passed),
            "refined": list(self.refined),
            "killed": list(self.killed),
            "summary": {
                "total": len(self.scores),
                "passed": len(self.passed),
                "refined": len(self.refined),
                "killed": len(self.killed),
            },
        }


def batch_reflect(
    hypotheses: list[dict],
    scores: list[ReflectionScore],
) -> tuple[list[dict], ReflectionResult]:
    """Filter hypothesis dicts using reflection scores.

    Returns (surviving_hypotheses, reflection_result).
    Surviving hypotheses include PASS and REFINE verdicts.
    REFINE hypotheses get a '_reflection_flag' key added.
    """
    score_map = {s.hypothesis_id: s for s in scores}
    result = ReflectionResult(scores=scores)

    surviving = []
    for h in hypotheses:
        h_id = h.get("id", "")
        sc = score_map.get(h_id)
        if sc is None:
            surviving.append(h)
            continue
        if sc.verdict == "KILL":
            continue
        if sc.verdict == "REFINE":
            h = dict(h)
            h["_reflection_flag"] = True
            h["_refinement_suggestion"] = sc.refinement_suggestion
        surviving.append(h)

    return surviving, result


def build_reflection_prompt(hypothesis: dict, source_phase: str = "unknown") -> str:
    """Build the 3-question self-critique prompt for a single hypothesis."""
    title = hypothesis.get("title", "Unknown")
    thesis = hypothesis.get("thesis", "")
    mechanism = hypothesis.get("mechanism", "")

    novelty_q = (
        'Is this hypothesis a RESTATEMENT of an obvious idea, or does it contain a non-obvious mechanism?'
        if source_phase == "first_principles"
        else 'Does the supporting evidence actually prove THIS hypothesis specifically, '
             'or could it support any vague positive conclusion?'
    )

    return f"""Self-critique this hypothesis. Score each question 1-10.

HYPOTHESIS: {title}
THESIS: {thesis}
MECHANISM: {mechanism}

Q1 (MECHANISM TEST): Can you trace the EXACT causal chain from founder's first action to revenue? Name every step.
Q2 (FALSIFICATION TEST): What SPECIFIC, OBSERVABLE evidence would prove this hypothesis WRONG within 2 weeks?
Q3 (NOVELTY/EVIDENCE TEST): {novelty_q}

Output JSON:
{{"mechanism_score": <1-10>, "falsification_score": <1-10>, "novelty_evidence_score": <1-10>, "critique_text": "<brief reasoning>", "refinement_suggestion": "<if score 3-5, suggest how to strengthen>"}}"""

