"""
KnowledgeGraph — structured, queryable evidence layer.
Tracks entities, claims, contradictions, and gaps.
Enables hypothesis verification and evidence-based debate.
"""

from __future__ import annotations

import json
import re
from dataclasses import dataclass, field
from typing import Optional


@dataclass
class KnowledgeNode:
    id: str
    entity: str
    entity_type: str
    attributes: dict = field(default_factory=dict)
    confidence: float = 0.5
    source_urls: list[str] = field(default_factory=list)

    def to_dict(self) -> dict:
        return {
            "id": self.id,
            "entity": self.entity,
            "entity_type": self.entity_type,
            "attributes": dict(self.attributes),
            "confidence": self.confidence,
            "source_urls": list(self.source_urls),
        }

    @classmethod
    def from_dict(cls, d: dict) -> KnowledgeNode:
        return cls(
            id=d["id"],
            entity=d["entity"],
            entity_type=d["entity_type"],
            attributes=d.get("attributes", {}),
            confidence=d.get("confidence", 0.5),
            source_urls=d.get("source_urls", []),
        )


@dataclass
class KnowledgeClaim:
    id: str
    subject_id: str
    predicate: str
    object_value: str
    evidence_type: str  # VERIFIED | INFERRED | CONTESTED | REFUTED
    evidence_sources: list[str] = field(default_factory=list)
    zone_tag: str = "?"
    timestamp: str = ""

    def to_dict(self) -> dict:
        return {
            "id": self.id,
            "subject_id": self.subject_id,
            "predicate": self.predicate,
            "object_value": self.object_value,
            "evidence_type": self.evidence_type,
            "evidence_sources": list(self.evidence_sources),
            "zone_tag": self.zone_tag,
            "timestamp": self.timestamp,
        }

    @classmethod
    def from_dict(cls, d: dict) -> KnowledgeClaim:
        return cls(
            id=d["id"],
            subject_id=d["subject_id"],
            predicate=d["predicate"],
            object_value=d["object_value"],
            evidence_type=d["evidence_type"],
            evidence_sources=d.get("evidence_sources", []),
            zone_tag=d.get("zone_tag", "?"),
            timestamp=d.get("timestamp", ""),
        )


OPPOSING_PREDICATES = {
    "market_growing": "market_shrinking",
    "market_shrinking": "market_growing",
    "costs_increasing": "costs_decreasing",
    "costs_decreasing": "costs_increasing",
    "demand_rising": "demand_falling",
    "demand_falling": "demand_rising",
    "profitable": "unprofitable",
    "unprofitable": "profitable",
    "price_rising": "price_falling",
    "price_falling": "price_rising",
}


@dataclass
class ContradictionEdge:
    claim_a_id: str
    claim_b_id: str
    description: str
    resolution: str = "UNRESOLVED"  # UNRESOLVED | A_WINS | B_WINS | BOTH_PARTIAL
    resolution_evidence: str = ""

    def to_dict(self) -> dict:
        return {
            "claim_a_id": self.claim_a_id,
            "claim_b_id": self.claim_b_id,
            "description": self.description,
            "resolution": self.resolution,
            "resolution_evidence": self.resolution_evidence,
        }

    @classmethod
    def from_dict(cls, d: dict) -> ContradictionEdge:
        return cls(
            claim_a_id=d["claim_a_id"],
            claim_b_id=d["claim_b_id"],
            description=d["description"],
            resolution=d.get("resolution", "UNRESOLVED"),
            resolution_evidence=d.get("resolution_evidence", ""),
        )


@dataclass
class EvidenceProfile:
    supporting_claims: list[KnowledgeClaim]
    contradicting_claims: list[KnowledgeClaim]
    related_contradictions: list[ContradictionEdge]
    gap_count: int
    strength_score: float

    def to_dict(self) -> dict:
        return {
            "supporting": [c.to_dict() for c in self.supporting_claims],
            "contradicting": [c.to_dict() for c in self.contradicting_claims],
            "contradictions": [c.to_dict() for c in self.related_contradictions],
            "gap_count": self.gap_count,
            "strength_score": round(self.strength_score, 3),
        }


class KnowledgeGraph:
    def __init__(self):
        self.nodes: dict[str, KnowledgeNode] = {}
        self.claims: dict[str, KnowledgeClaim] = {}
        self.contradictions: list[ContradictionEdge] = []
        self._node_counter = 0
        self._claim_counter = 0

    def add_node(
        self,
        entity: str,
        entity_type: str,
        attributes: Optional[dict] = None,
        confidence: float = 0.5,
        source_urls: Optional[list[str]] = None,
    ) -> KnowledgeNode:
        self._node_counter += 1
        node_id = f"N{self._node_counter:03d}"
        node = KnowledgeNode(
            id=node_id,
            entity=entity,
            entity_type=entity_type,
            attributes=attributes or {},
            confidence=confidence,
            source_urls=source_urls or [],
        )
        self.nodes[node_id] = node
        return node

    def add_claim(
        self,
        subject_id: str,
        predicate: str,
        object_value: str,
        evidence_type: str = "INFERRED",
