"""
VaultToGraphBuilder — parses evidence vault markdown into KnowledgeGraph.
Extracts entities, claims, zone tags, and auto-detects contradictions.
"""

from __future__ import annotations

import re
from typing import Optional

from .knowledge_graph import KnowledgeGraph


ZONE_TO_EVIDENCE_TYPE = {
    "[K]": "VERIFIED",
    "[T]": "INFERRED",
    "[?]": "CONTESTED",
    "K": "VERIFIED",
    "T": "INFERRED",
    "?": "CONTESTED",
}

ENTITY_TYPE_KEYWORDS = {
    "COMPANY": ["company", "corp", "inc", "ltd", "group", "factory", "brand", "exporter", "importer"],
    "MARKET": ["market", "segment", "sector", "industry", "demand", "channel"],
    "PRODUCT": ["product", "coffee", "bean", "robusta", "arabica", "grade", "blend"],
    "TECHNOLOGY": ["platform", "regulation", "eudr", "certification", "system", "software"],
    "CONCEPT": ["price", "tariff", "elo", "futures", "certificate", "standard", "trend"],
    "PERSON": ["founder", "ceo", "director", "manager"],
}


class VaultToGraphBuilder:
    def __init__(self):
        self._entity_cache: dict[str, str] = {}

    def build(self, vault_text: str) -> KnowledgeGraph:
        graph = KnowledgeGraph()
        sections = self._split_sections(vault_text)

        for section in sections:
            self._extract_from_section(graph, section)

        graph.detect_contradictions()
        return graph

    def _split_sections(self, text: str) -> list[dict]:
        sections = []
        current_header = ""
        current_lines: list[str] = []

        for line in text.split("\n"):
            if line.startswith("## ") or line.startswith("### "):
                if current_lines:
                    sections.append({"header": current_header, "body": "\n".join(current_lines)})
                current_header = line.lstrip("#").strip()
                current_lines = []
            else:
                current_lines.append(line)

        if current_lines:
            sections.append({"header": current_header, "body": "\n".join(current_lines)})

        return sections

    def _extract_from_section(self, graph: KnowledgeGraph, section: dict):
        body = section["body"]
        header = section["header"]

        entities = self._extract_entities(body)
        for entity_name, entity_type in entities:
            if entity_name not in self._entity_cache:
                node = graph.add_node(entity_name, entity_type)
                self._entity_cache[entity_name] = node.id

        claims = self._extract_claims(body)
        for claim_data in claims:
            subject_name = claim_data.get("subject", "")
