"""
ConvergenceChecker — dynamic convergence for refinement loop.
Dual signal: ranking stability OR Elo delta rate.
Replaces fixed round cap with intelligent stopping.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Optional


ELO_DELTA_THRESHOLD = 0.05
MAX_ROUNDS = 5
MIN_ROUNDS = 2


@dataclass
class EvolutionEntry:
    round: int
    action: str  # STRENGTHENED | ATTACKED | EVOLVED | MERGED
    description: str
    evidence_delta: str = ""
    score_before: float = 0.0
    score_after: float = 0.0

    def to_dict(self) -> dict:
        return {
            "round": self.round,
            "action": self.action,
            "description": self.description,
            "evidence_delta": self.evidence_delta,
            "score_before": self.score_before,
            "score_after": self.score_after,
        }

    @classmethod
    def from_dict(cls, d: dict) -> EvolutionEntry:
        return cls(
            round=d["round"],
            action=d["action"],
            description=d["description"],
            evidence_delta=d.get("evidence_delta", ""),
            score_before=d.get("score_before", 0.0),
            score_after=d.get("score_after", 0.0),
        )


@dataclass
class RefinementRound:
    round_number: int
    top_3_ids: list[str]
    top_3_elos: list[float]
    hypotheses_refined: int = 0
    hypotheses_evolved: int = 0
    searches_executed: int = 0
    contradictions_found: int = 0
    evidence_upgrades: int = 0
    diversity_report: dict = field(default_factory=dict)

    def to_dict(self) -> dict:
        return {
            "round_number": self.round_number,
            "top_3_ids": list(self.top_3_ids),
            "top_3_elos": list(self.top_3_elos),
            "hypotheses_refined": self.hypotheses_refined,
            "hypotheses_evolved": self.hypotheses_evolved,
            "searches_executed": self.searches_executed,
            "contradictions_found": self.contradictions_found,
            "evidence_upgrades": self.evidence_upgrades,
            "diversity_report": dict(self.diversity_report),
        }

    @classmethod
    def from_dict(cls, d: dict) -> RefinementRound:
        return cls(
            round_number=d["round_number"],
            top_3_ids=d["top_3_ids"],
            top_3_elos=d["top_3_elos"],
            hypotheses_refined=d.get("hypotheses_refined", 0),
            hypotheses_evolved=d.get("hypotheses_evolved", 0),
            searches_executed=d.get("searches_executed", 0),
            contradictions_found=d.get("contradictions_found", 0),
            evidence_upgrades=d.get("evidence_upgrades", 0),
            diversity_report=d.get("diversity_report", {}),
        )


@dataclass
class RefinementResult:
    rounds: list[RefinementRound]
    converged: bool
    convergence_reason: str
    final_top_3: list[str]
    evolution_traces: dict[str, list[EvolutionEntry]] = field(default_factory=dict)
    total_searches: int = 0

    @property
    def elo_trajectory(self) -> list[float]:
        return [r.top_3_elos[0] if r.top_3_elos else 0.0 for r in self.rounds]

    def to_dict(self) -> dict:
        traces = {}
        for hid, entries in self.evolution_traces.items():
            traces[hid] = [e.to_dict() for e in entries]
        return {
            "rounds": [r.to_dict() for r in self.rounds],
            "converged": self.converged,
            "convergence_reason": self.convergence_reason,
            "final_top_3": list(self.final_top_3),
            "evolution_traces": traces,
            "total_searches": self.total_searches,
            "elo_trajectory": self.elo_trajectory,
        }

    @classmethod
    def from_dict(cls, d: dict) -> RefinementResult:
        traces = {}
        for hid, entries in d.get("evolution_traces", {}).items():
            traces[hid] = [EvolutionEntry.from_dict(e) for e in entries]
        return cls(
            rounds=[RefinementRound.from_dict(r) for r in d["rounds"]],
            converged=d["converged"],
            convergence_reason=d["convergence_reason"],
            final_top_3=d["final_top_3"],
            evolution_traces=traces,
            total_searches=d.get("total_searches", 0),
        )


def check_convergence(rounds: list[RefinementRound]) -> tuple[bool, str]:
    """Dual convergence signal.
    Signal A: top-3 IDs stable across 2 consecutive rounds.
    Signal B: top-1 Elo delta < threshold.
    Hard cap at MAX_ROUNDS.
    """
    if len(rounds) < MIN_ROUNDS:
        return False, "min_rounds_not_met"

    if len(rounds) >= MAX_ROUNDS:
        return True, "max_rounds"

    if rounds[-1].top_3_ids == rounds[-2].top_3_ids:
        return True, "ranking_stable"

    prev_elo = rounds[-2].top_3_elos[0] if rounds[-2].top_3_elos else 0
    curr_elo = rounds[-1].top_3_elos[0] if rounds[-1].top_3_elos else 0
    if prev_elo > 0:
        delta = abs(curr_elo - prev_elo) / prev_elo
        if delta < ELO_DELTA_THRESHOLD:
            return True, "elo_stable"

    return False, "improving"


def should_continue(rounds: list[RefinementRound]) -> tuple[bool, str]:
    """Returns (True, reason) if another round would help."""
    converged, reason = check_convergence(rounds)
    if converged:
        return False, reason

    if len(rounds) >= 2:
        deltas = _compute_deltas(rounds)
        if len(deltas) >= 2 and deltas[-1] > deltas[-2]:
            return True, "elo_accelerating"

    return True, "improving"


def _compute_deltas(rounds: list[RefinementRound]) -> list[float]:
    deltas = []
    for i in range(1, len(rounds)):
        prev = rounds[i - 1].top_3_elos[0] if rounds[i - 1].top_3_elos else 0
        curr = rounds[i].top_3_elos[0] if rounds[i].top_3_elos else 0
        if prev > 0:
            deltas.append(abs(curr - prev) / prev)
        else:
            deltas.append(0.0)
    return deltas


def build_result(
    rounds: list[RefinementRound],
    evolution_traces: Optional[dict[str, list[EvolutionEntry]]] = None,
) -> RefinementResult:
    """Build final RefinementResult from completed rounds."""
    converged, reason = check_convergence(rounds)
    final_top_3 = rounds[-1].top_3_ids if rounds else []
    total_searches = sum(r.searches_executed for r in rounds)
    return RefinementResult(
        rounds=rounds,
        converged=converged,
        convergence_reason=reason,
        final_top_3=final_top_3,
        evolution_traces=evolution_traces or {},
        total_searches=total_searches,
    )

