def _compute_deltas(rounds: list[RefinementRound]) -> list[float]:
    deltas = []
    for i in range(1, len(rounds)):
        prev = rounds[i - 1].top_3_elos[0] if rounds[i - 1].top_3_elos else 0
        curr = rounds[i].top_3_elos[0] if rounds[i].top_3_elos else 0
        if prev > 0:
            deltas.append(abs(curr - prev) / prev)
        else:
            deltas.append(0.0)
    return deltas


def build_result(
    rounds: list[RefinementRound],
    evolution_traces: Optional[dict[str, list[EvolutionEntry]]] = None,
) -> RefinementResult:
    """Build final RefinementResult from completed rounds."""
    converged, reason = check_convergence(rounds)
    final_top_3 = rounds[-1].top_3_ids if rounds else []
    total_searches = sum(r.searches_executed for r in rounds)
    return RefinementResult(
        rounds=rounds,
        converged=converged,
        convergence_reason=reason,
