@dataclass
class DebatePrompt:
    hypothesis_a_id: str
    hypothesis_b_id: str
    prompt_text: str
    evidence_a_summary: str
    evidence_b_summary: str
    is_evidence_backed: bool

    def to_dict(self) -> dict:
