            "hypothesis_b_id": self.hypothesis_b_id,
            "evidence_a_summary": self.evidence_a_summary,
            "evidence_b_summary": self.evidence_b_summary,
            "is_evidence_backed": self.is_evidence_backed,
            "prompt_length": len(self.prompt_text),
        }


def _format_claims(claims: list, label: str, max_claims: int = 5) -> str:
    if not claims:
        return f"  {label}: (none found in knowledge graph)"
    lines = []
    for c in claims[:max_claims]:
        zone = getattr(c, "zone_tag", "?")
        pred = getattr(c, "predicate", "")
        val = getattr(c, "object_value", "")
        lines.append(f"  [{zone}] {pred}: {val}")
    return f"  {label}:\n" + "\n".join(lines)


def _format_contradictions(contradictions: list, max_items: int = 3) -> str:
    if not contradictions:
        return ""
    lines = ["  Active contradictions:"]
    for c in contradictions[:max_items]:
        desc = getattr(c, "description", str(c))
        lines.append(f"  - {desc}")
    return "\n".join(lines)


def build_evidence_debate_prompt(
    hypothesis_a: dict,
    hypothesis_b: dict,
    graph: Optional[object] = None,
) -> DebatePrompt:
    """Build an evidence-backed debate prompt for two competing hypotheses.

    If graph is None or empty, falls back to opinion-based debate.
    """
    a_id = hypothesis_a.get("id", "A")
    b_id = hypothesis_b.get("id", "B")
    a_title = hypothesis_a.get("title", "Hypothesis A")
    b_title = hypothesis_b.get("title", "Hypothesis B")
    a_thesis = hypothesis_a.get("thesis", "")
    b_thesis = hypothesis_b.get("thesis", "")
    a_mechanism = hypothesis_a.get("mechanism", "")
    b_mechanism = hypothesis_b.get("mechanism", "")

    is_evidence_backed = False
    evidence_a_text = ""
    evidence_b_text = ""
    evidence_a_summary = "no graph"
    evidence_b_summary = "no graph"

    if graph is not None:
        try:
            profile_a = graph.query_hypothesis(f"{a_title} {a_thesis} {a_mechanism}")
            profile_b = graph.query_hypothesis(f"{b_title} {b_thesis} {b_mechanism}")

            has_evidence = (
                len(profile_a.supporting_claims) + len(profile_a.contradicting_claims)
                + len(profile_b.supporting_claims) + len(profile_b.contradicting_claims)
            ) > 0

            if has_evidence:
                is_evidence_backed = True
                evidence_a_text = (
                    _format_claims(profile_a.supporting_claims, "Supporting evidence")
                    + "\n"
                    + _format_claims(profile_a.contradicting_claims, "Counter-evidence")
                    + "\n"
                    + _format_contradictions(profile_a.related_contradictions)
                )
                evidence_b_text = (
                    _format_claims(profile_b.supporting_claims, "Supporting evidence")
                    + "\n"
                    + _format_claims(profile_b.contradicting_claims, "Counter-evidence")
                    + "\n"
                    + _format_contradictions(profile_b.related_contradictions)
                )
                evidence_a_summary = (
                    f"{len(profile_a.supporting_claims)}S/{len(profile_a.contradicting_claims)}C, "
                    f"strength={profile_a.strength_score:.2f}"
                )
                evidence_b_summary = (
                    f"{len(profile_b.supporting_claims)}S/{len(profile_b.contradicting_claims)}C, "
                    f"strength={profile_b.strength_score:.2f}"
                )
        except Exception:
            pass

    if is_evidence_backed:
        prompt = f"""EVIDENCE-BASED DEBATE: {a_title} vs {b_title}

=== HYPOTHESIS A: {a_title} ===
Thesis: {a_thesis}
Mechanism: {a_mechanism}
{evidence_a_text}

=== HYPOTHESIS B: {b_title} ===
Thesis: {b_thesis}
Mechanism: {b_mechanism}
{evidence_b_text}

DEBATE RULES:
1. A attacks B using B's counter-evidence + A's supporting evidence
2. B attacks A using A's counter-evidence + B's supporting evidence
3. Each attack MUST reference SPECIFIC claims from the evidence above
4. Judge based on which mechanism SURVIVES attacks with more intact evidence

OUTPUT JSON:
{{"winner": "A" or "B", "winner_id": "<id>", "reasoning": "<which evidence survived>", "key_evidence": "<the decisive claim>"}}"""
    else:
        prompt = f"""DEBATE: {a_title} vs {b_title}

HYPOTHESIS A [{a_id}]: {a_thesis}
Mechanism: {a_mechanism}

HYPOTHESIS B [{b_id}]: {b_thesis}
Mechanism: {b_mechanism}

Compare these hypotheses on: mechanism clarity, falsifiability, founder fit, revenue potential.
Which is the stronger opportunity and why?

OUTPUT JSON:
{{"winner": "A" or "B", "winner_id": "<id>", "reasoning": "<why>"}}"""

    return DebatePrompt(
        hypothesis_a_id=a_id,
        hypothesis_b_id=b_id,
        prompt_text=prompt,
        evidence_a_summary=evidence_a_summary,
        evidence_b_summary=evidence_b_summary,
        is_evidence_backed=is_evidence_backed,
    )


def extract_debate_winner(debate_response: str, a_id: str, b_id: str) -> dict:
    """Parse LLM debate response for winner. Returns dict with winner_id + reasoning."""
    import json
    import re

    try:
        json_match = re.search(r'\{[^}]+\}', debate_response, re.DOTALL)
        if json_match:
            data = json.loads(json_match.group())
            winner_field = data.get("winner", "").upper()
            winner_id = data.get("winner_id", "")
            if not winner_id:
                winner_id = a_id if winner_field == "A" else b_id
            return {
                "winner_id": winner_id,
                "reasoning": data.get("reasoning", ""),
                "key_evidence": data.get("key_evidence", ""),
            }
    except (json.JSONDecodeError, AttributeError):
        pass

    response_lower = debate_response.lower()
    a_mentions = response_lower.count(a_id.lower())
    b_mentions = response_lower.count(b_id.lower())
    if "winner" in response_lower:
        if a_id.lower() in response_lower[response_lower.index("winner"):response_lower.index("winner") + 50]:
            return {"winner_id": a_id, "reasoning": "parsed from text", "key_evidence": ""}
        if b_id.lower() in response_lower[response_lower.index("winner"):response_lower.index("winner") + 50]:
            return {"winner_id": b_id, "reasoning": "parsed from text", "key_evidence": ""}

    return {"winner_id": a_id if a_mentions >= b_mentions else b_id, "reasoning": "fallback: mention count", "key_evidence": ""}

