"""
ProximityEnforcer — prevents hypothesis pool premature convergence.
Classifies archetypes, penalizes proximate pairs, enforces top-3 diversity.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Optional


ARCHETYPES = {
    "SAAS_TOOL": ["software", "platform", "tool", "dashboard", "app", "api", "saas"],
    "ARBITRAGE": ["arbitrage", "price gap", "spread", "delta", "cross-border", "waste", "defect"],
    "MARKETPLACE": ["marketplace", "matching", "connect", "two-sided", "exchange", "aggregat"],
    "SERVICE": ["agency", "consulting", "freelance", "done-for-you", "service", "broker"],
    "CONTENT": ["course", "training", "community", "newsletter", "media", "sample"],
    "INFRASTRUCTURE": ["compliance", "certification", "testing", "audit", "infrastructure", "microclimate"],
    "INTELLIGENCE": ["data", "intelligence", "insight", "research", "advisory", "lead-gen", "funnel"],
}

PROXIMITY_PENALTY = 50


@dataclass
class RankedHypothesis:
    id: str
    title: str
    elo: float
    archetype: str = ""
    text: str = ""

    def to_dict(self) -> dict:
        return {
            "id": self.id,
            "title": self.title,
            "elo": self.elo,
            "archetype": self.archetype,
        }


@dataclass
class DiversityReport:
    round_number: int
    archetype_counts: dict[str, int] = field(default_factory=dict)
    unique_archetypes_in_top5: int = 0
    proximity_penalties_applied: int = 0
    diversity_swaps_applied: int = 0

    @property
    def diversity_score(self) -> float:
        return self.unique_archetypes_in_top5 / 5.0 if self.unique_archetypes_in_top5 else 0.0

    @property
    def is_healthy(self) -> bool:
        return self.unique_archetypes_in_top5 >= 3

    def to_dict(self) -> dict:
        return {
            "round_number": self.round_number,
            "archetype_counts": dict(self.archetype_counts),
            "unique_archetypes_in_top5": self.unique_archetypes_in_top5,
            "proximity_penalties_applied": self.proximity_penalties_applied,
            "diversity_swaps_applied": self.diversity_swaps_applied,
            "diversity_score": round(self.diversity_score, 2),
            "is_healthy": self.is_healthy,
        }


def classify_archetype(text: str) -> str:
    text_lower = text.lower()
    scores: dict[str, int] = {}
    for archetype, keywords in ARCHETYPES.items():
        count = sum(1 for kw in keywords if kw in text_lower)
        if count > 0:
            scores[archetype] = count
    if scores:
        return max(scores, key=scores.get)
    return "OTHER"


def word_overlap_similarity(text_a: str, text_b: str) -> float:
    words_a = set(text_a.lower().split())
    words_b = set(text_b.lower().split())
    if not words_a or not words_b:
        return 0.0
    intersection = words_a & words_b
    union = words_a | words_b
    return len(intersection) / len(union) if union else 0.0


def detect_proximate_pairs(
    hypotheses: list[RankedHypothesis],
    similarity_threshold: float = 0.7,
) -> list[tuple[str, str]]:
    proximate = []
    for i, a in enumerate(hypotheses):
        for b in hypotheses[i + 1:]:
            if a.archetype != b.archetype:
                continue
            if a.archetype == "OTHER":
                continue
            sim = word_overlap_similarity(
                f"{a.title} {a.text}",
                f"{b.title} {b.text}",
            )
            if sim >= similarity_threshold:
                proximate.append((a.id, b.id))
    return proximate


def apply_proximity_penalties(
    rankings: list[RankedHypothesis],
    similarity_threshold: float = 0.7,
) -> tuple[list[RankedHypothesis], int]:
    """Penalize lower-ranked member of each proximate pair by PROXIMITY_PENALTY Elo points."""
    pairs = detect_proximate_pairs(rankings, similarity_threshold)
    penalties_applied = 0

    id_to_rank = {h.id: i for i, h in enumerate(rankings)}
    penalized_ids: set[str] = set()

    for a_id, b_id in pairs:
        rank_a = id_to_rank.get(a_id, 999)
        rank_b = id_to_rank.get(b_id, 999)
        lower_id = b_id if rank_a < rank_b else a_id
        if lower_id not in penalized_ids:
            for h in rankings:
                if h.id == lower_id:
                    h.elo -= PROXIMITY_PENALTY
                    penalized_ids.add(lower_id)
                    penalties_applied += 1
                    break

    rankings.sort(key=lambda h: h.elo, reverse=True)
    return rankings, penalties_applied


def enforce_top3_diversity(
    rankings: list[RankedHypothesis],
) -> tuple[list[RankedHypothesis], int]:
    """If top-3 all same archetype, swap #3 with highest-ranked different archetype."""
    if len(rankings) < 4:
        return rankings, 0

    top3_archetypes = [h.archetype for h in rankings[:3]]
    if len(set(top3_archetypes)) > 1:
        return rankings, 0

    dominant = top3_archetypes[0]
    for i in range(3, len(rankings)):
        if rankings[i].archetype != dominant:
            rankings[2], rankings[i] = rankings[i], rankings[2]
            return rankings, 1

    return rankings, 0


def generate_report(
    rankings: list[RankedHypothesis],
    round_number: int,
    penalties_applied: int = 0,
    swaps_applied: int = 0,
) -> DiversityReport:
    counts: dict[str, int] = {}
    for h in rankings:
        counts[h.archetype] = counts.get(h.archetype, 0) + 1

    unique_in_top5 = len({h.archetype for h in rankings[:5]}) if len(rankings) >= 5 else len({h.archetype for h in rankings})

    return DiversityReport(
        round_number=round_number,
        archetype_counts=counts,
        unique_archetypes_in_top5=unique_in_top5,
        proximity_penalties_applied=penalties_applied,
        diversity_swaps_applied=swaps_applied,
    )


def enforce_all(
    rankings: list[RankedHypothesis],
    round_number: int,
    similarity_threshold: float = 0.7,
) -> tuple[list[RankedHypothesis], DiversityReport]:
    """Run full enforcement pipeline: classify → penalize → diversity tax → report."""
    for h in rankings:
        if not h.archetype:
            h.archetype = classify_archetype(f"{h.title} {h.text}")

    rankings, penalties = apply_proximity_penalties(rankings, similarity_threshold)
    rankings, swaps = enforce_top3_diversity(rankings)
    report = generate_report(rankings, round_number, penalties, swaps)
    return rankings, report

