"""
GraphProtocol — shared interface for MoneyFlowGraph and KnowledgeGraph.
Both graph types implement this so refinement loop and IC can share code.
"""

from __future__ import annotations

from abc import ABC, abstractmethod
from typing import Any


class GraphProtocol(ABC):
    @abstractmethod
    def find_gaps(self) -> list[dict]:
        """Return claims/edges with insufficient evidence."""

    @abstractmethod
    def overall_confidence(self) -> float:
        """0.0-1.0 aggregate confidence score."""

    @abstractmethod
    def to_dict(self) -> dict:
        """Serialize graph to dict."""

    def node_count(self) -> int:
        return len(getattr(self, "nodes", {}))

    def edge_or_claim_count(self) -> int:
        edges = getattr(self, "edges", {})
        claims = getattr(self, "claims", {})
        return len(edges) + len(claims)

"""
ConvergenceProtocol — shared convergence interface for IC and refinement loop.
Both systems use the same dual-signal logic: ranking stability + delta rate.
"""

from __future__ import annotations

from abc import ABC, abstractmethod
from dataclasses import dataclass
from typing import Any


@dataclass
class ConvergenceState:
    cycle: int
    converged: bool
    reason: str
    top_ids: list[str]
    top_scores: list[float]
    delta_rate: float = 0.0

    def to_dict(self) -> dict:
        return {
            "cycle": self.cycle,
            "converged": self.converged,
            "reason": self.reason,
            "top_ids": list(self.top_ids),
            "top_scores": list(self.top_scores),
            "delta_rate": round(self.delta_rate, 4),
        }


class ConvergenceProtocol(ABC):
    @abstractmethod
    def check(self, history: list[Any]) -> ConvergenceState:
        """Check convergence against history of rounds/cycles."""

    @abstractmethod
    def should_continue(self, history: list[Any]) -> tuple[bool, str]:
        """Returns (True, reason) if more cycles help."""


class DualSignalConvergence(ConvergenceProtocol):
    """Concrete implementation: ranking stable OR score delta < threshold."""

    def __init__(
        self,
        delta_threshold: float = 0.05,
        max_cycles: int = 5,
        min_cycles: int = 2,
        top_n: int = 3,
    ):
        self.delta_threshold = delta_threshold
        self.max_cycles = max_cycles
        self.min_cycles = min_cycles
        self.top_n = top_n

    def check(self, history: list[Any]) -> ConvergenceState:
        if len(history) < self.min_cycles:
            return ConvergenceState(
                cycle=len(history),
                converged=False,
                reason="min_cycles_not_met",
                top_ids=self._get_ids(history[-1]) if history else [],
                top_scores=self._get_scores(history[-1]) if history else [],
            )

        curr_ids = self._get_ids(history[-1])
        prev_ids = self._get_ids(history[-2])
        curr_scores = self._get_scores(history[-1])
        prev_scores = self._get_scores(history[-2])

        delta = self._compute_delta(curr_scores, prev_scores)

        if len(history) >= self.max_cycles:
            return ConvergenceState(
                cycle=len(history), converged=True, reason="max_cycles",
                top_ids=curr_ids, top_scores=curr_scores, delta_rate=delta,
            )

        if curr_ids == prev_ids:
            return ConvergenceState(
                cycle=len(history), converged=True, reason="ranking_stable",
                top_ids=curr_ids, top_scores=curr_scores, delta_rate=delta,
            )

        if delta < self.delta_threshold:
            return ConvergenceState(
                cycle=len(history), converged=True, reason="score_stable",
                top_ids=curr_ids, top_scores=curr_scores, delta_rate=delta,
            )

        return ConvergenceState(
            cycle=len(history), converged=False, reason="improving",
            top_ids=curr_ids, top_scores=curr_scores, delta_rate=delta,
        )

    def should_continue(self, history: list[Any]) -> tuple[bool, str]:
        state = self.check(history)
        if state.converged:
            return False, state.reason
        return True, state.reason

    def _get_ids(self, entry: Any) -> list[str]:
        if hasattr(entry, "top_3_ids"):
            return entry.top_3_ids[:self.top_n]
        if isinstance(entry, dict):
            return entry.get("top_ids", [])[:self.top_n]
        return []

    def _get_scores(self, entry: Any) -> list[float]:
        if hasattr(entry, "top_3_elos"):
            return entry.top_3_elos[:self.top_n]
        if isinstance(entry, dict):
            return entry.get("top_scores", [])[:self.top_n]
        return []

    def _compute_delta(self, curr: list[float], prev: list[float]) -> float:
        if not curr or not prev or prev[0] <= 0:
            return 0.0
        return abs(curr[0] - prev[0]) / prev[0]

